#include <iostream>
#include <type_traits>

int main() {
    auto val_u = 174u;
    auto val_l = 8358L;
    auto val_ull = 9876543210ull;
    auto val_f = 1.28f;
    auto val_d = 3.14;
    auto val_ld = 3.14159L;

    std::cout << "val_u unsigned: " << std::is_unsigned_v<decltype(val_u)> << "\n";
    std::cout << "val_l is long: " << std::is_same_v<decltype(val_l), long> << "\n";
    std::cout << "val_ull is unsigned long long: " << std::is_same_v<decltype(val_ull), unsigned long long> << "\n";
    std::cout << "val_f is float: " << std::is_same_v<decltype(val_f), float> << "\n";
    std::cout << "val_d is double: " << std::is_same_v<decltype(val_d), double> << "\n";
    std::cout << "val_ld is long double: " << std::is_same_v<decltype(val_ld), long double> << "\n";

    return 0;
}

#include <iostream>

// We demonstrate a deterministic dispatcher pattern modeling
// how a signal dispatch table routes integer codes to handlers.
enum StandardSignal {
    Signal_ABRT = 1,
    Signal_INT  = 2,
    Signal_SEGV = 11,
    Signal_TERM = 15
};

using SignalCallback = void(*)(int);

void onInterrupt(int sig) {
    std::cout << "Interception triggered: signal code " << sig << " (SIGINT received).\n";
}

void onTermination(int sig) {
    std::cout << "Termination handled: signal code " << sig << " (SIGTERM received).\n";
}

struct SignalDispatcher {
    SignalCallback handlers[32] = { nullptr };

    void registerHandler(int sig, SignalCallback handler) {
        if (sig >= 0 && sig < 32) {
            handlers[sig] = handler;
        }
    }

    void dispatch(int sig) {
        if (sig >= 0 && sig < 32 && handlers[sig]) {
            handlers[sig](sig);
        }
    }
};

int main() {
    SignalDispatcher dispatcher;
    dispatcher.registerHandler(Signal_INT, onInterrupt);
    dispatcher.registerHandler(Signal_TERM, onTermination);

    std::cout << "Simulating loop step 1...\n";
    std::cout << "Simulating loop step 2...\n";
    dispatcher.dispatch(Signal_INT);
    std::cout << "Resuming normal processing after handling signal.\n";

    return 0;
}
